sys_script_client.script:
function onSubmit() {
    var name = (g_form.getValue('name') || '').trim();
    if (!name) {
        return true;
    }

    var normalized = name.toLowerCase();

    // Check if name already exists in scratchpad
    if (g_scratchpad.existingQualifications && g_scratchpad.existingQualifications.indexOf(normalized) !== -1) {
        // Clear old messages and show ONLY our clean message
        g_form.clearMessages();
        g_form.addErrorMessage('Qualification "' + name + '" already exists. Duplicate names are not allowed.');

        // STOP form submission completely (prevents the 2 system messages!)
        return false;
    }

    return true;
}
